// The boards come from the connection's settings (trello-boards:<workflow_id>);
// a connection without boards polls nothing.
// Look back 2.5 minutes on a 2-minute schedule, like the GitHub and Linear pollers.
// The overlap re-sends a few actions; POST /events drops repeated event IDs.
const boards = $input.first().json.value;
const since = new Date(Date.now() - 150000).toISOString();
return (Array.isArray(boards) ? boards : [])
  .filter(boardId => typeof boardId === 'string' && /^(?:[A-Za-z0-9]{8}|[a-fA-F0-9]{24})$/.test(boardId))
  .map(boardId => ({ json: { boardId, since } }));

const events = [];
for (const { json: page } of $input.all()) {
  if (!Array.isArray(page.body)) throw new Error('Unexpected Trello board actions response');
  for (const action of page.body) {
    const data = action.data ?? {};
    const card = data.card;
    if (!card?.id || !action.id || !Number.isFinite(Date.parse(action.date))) continue;

    let eventType;
    let body;
    const participants = [];
    switch (action.type) {
      case 'createCard':
      case 'copyCard':
      case 'emailCard':
      case 'convertToCardFromCheckItem':
        eventType = 'card_created';
        body = data.list?.name ? 'Card created in ' + data.list.name + '.' : 'Card created.';
        break;
      case 'commentCard':
        eventType = 'card_commented';
        body = data.text ?? '';
        break;
      case 'addMemberToCard':
      case 'removeMemberFromCard': {
        const added = action.type === 'addMemberToCard';
        const member = action.member ?? data.member;
        const handle = member?.username || member?.id || data.idMember || '';
        const name = member?.fullName || handle;
        eventType = added ? 'card_member_added' : 'card_member_removed';
        body = (name || 'A member') + (added ? ' was added to the card.' : ' was removed from the card.');
        if (added && handle) participants.push({ role: 'assignee', name, email: '', handle });
        break;
      }
      case 'moveCardToBoard':
      case 'moveCardFromBoard':
        eventType = 'card_moved';
        body = action.type === 'moveCardToBoard' ? 'Card moved onto this board.' : 'Card moved off this board.';
        break;
      case 'updateCard': {
        const old = data.old ?? {};
        if (Object.hasOwn(old, 'closed') && typeof card.closed === 'boolean') {
          eventType = card.closed ? 'card_archived' : 'card_unarchived';
          body = card.closed ? 'Card archived.' : 'Card unarchived.';
        } else if (Object.hasOwn(old, 'dueComplete') && typeof card.dueComplete === 'boolean') {
          eventType = card.dueComplete ? 'card_completed' : 'card_reopened';
          body = card.dueComplete ? 'Card marked complete.' : 'Card marked incomplete.';
        } else if (data.listBefore && data.listAfter) {
          eventType = 'card_moved';
          body = 'Card moved from ' + data.listBefore.name + ' to ' + data.listAfter.name + '.';
        } else if (['name', 'desc', 'due', 'start'].some(field => Object.hasOwn(old, field))) {
          eventType = 'card_updated';
          body = Object.hasOwn(old, 'desc') && card.desc ? card.desc : 'Card details updated.';
        }
        break;
      }
    }
    if (!eventType) continue;

    const actor = action.memberCreator;
    events.push({
      json: {
        event_id: 'evt_trello_' + $workflow.id + '_' + action.id,
        timestamp: action.date,
        source: {
          platform: 'trello',
          connection_id: $workflow.id,
          raw_event_type: eventType,
        },
        actor: {
          name: actor?.fullName || actor?.username || 'Unknown',
          email: '',
          platform_handle: actor?.username || action.idMemberCreator || null,
        },
        subject: {
          type: 'ticket',
          // A moved card keeps its Trello ID, so the workflow scopes its history to the board connection.
          id: $workflow.id + ':' + card.id,
          title: card.name || 'Trello card',
          url: /^[A-Za-z0-9]{8}$/.test(card.shortLink ?? '') ? 'https://trello.com/c/' + card.shortLink : null,
        },
        content: {
          body,
          attachments: [],
          metadata: {
            trello_card_id: card.id,
            trello_board_id: data.board?.id ?? null,
            trello_board_name: data.board?.name ?? null,
            trello_list_name: data.listAfter?.name ?? data.list?.name ?? null,
            participants,
          },
        },
      },
    });
  }
}
return events.sort((a, b) => Date.parse(a.json.timestamp) - Date.parse(b.json.timestamp)
  || a.json.event_id.localeCompare(b.json.event_id));

// Runs on the error output of Fetch Trello Actions (onError: continueErrorOutput),
// so one unreadable board does not stop the other boards from being ingested.
// Each failed item keeps its input fields (boardId) plus n8n's `error`, and is
// reported to the engine's /ingestion-errors endpoint (same schema as the Laya
// error handler workflow) so it shows up in Audit with a per-board message.
// The engine coalesces repeats by (workflow, node, message).

// With a credential attached, n8n hands the Code node a NodeApiError whose
// numeric code is not serialized: only its canned `message` (keyed by status
// in n8n's STATUS_CODE_MESSAGES) and `description` (Trello's own message, e.g.
// "invalid token") survive. Try the numeric fields first, then map the canned
// message back to a status.
const MESSAGE_TO_STATUS = [
  ['Bad request', 400],
  ['Authorization failed', 401],
  ['Forbidden', 403],
  ['could not be found', 404],
  ['too many requests', 429],
  ['spacing your requests', 429],
];
function statusOf(err) {
  const direct = Number(err.httpCode ?? err.status ?? err.statusCode);
  if (Number.isFinite(direct) && direct > 0) return direct;
  const msg = String(err.message || '');
  for (const [needle, status] of MESSAGE_TO_STATUS) {
    if (msg.includes(needle)) return status;
  }
  return null;
}

const node = $prevNode.name;
return $input.all().map(item => {
  const d = item.json || {};
  const err = d.error || {};
  const board = d.boardId || 'unknown board';
  const status = statusOf(err);
  const hint = status === 400 ? 'Trello did not accept this board ID'
    : status === 401 ? 'API key or token invalid or revoked'
    : status === 403 ? 'token lacks access to this board'
    : status === 404 ? 'board not found, or not readable with this token'
    : status === 429 ? 'rate limited'
    : 'request failed';
  const detail = err.description || err.message || '';
  return { json: {
    workflow_id: $workflow.id,
    workflow_name: $workflow.name,
    platform: 'trello',
    node_name: node,
    node_type: 'n8n-nodes-base.httpRequest',
    error_name: err.name || 'TrelloRequestError',
    error_message: 'Trello ' + (status || 'error') + ' for board ' + board + ': ' + hint
      + (detail ? ' (' + detail + ')' : ''),
    error_http_code: status,
    error_details: { board, status, message: err.message, description: err.description },
    execution_id: String($execution.id || ''),
    execution_mode: $execution.mode || '',
    occurred_at: new Date().toISOString()
  } };
});
